package com.yeyamo_mobile.api.analytics_service.business;

import com.fasterxml.jackson.databind.JsonNode;import java.math.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;

@Service public class TerritorialAnalyticsService {
 private final CountryActivityDailyRepository countries;private final CityActivityDailyRepository cities;private final CountryRevenueDailyRepository revenues;private final CultureCountryDailyRepository cultures;private final ArtisanCountryDailyRepository artisans;
 public TerritorialAnalyticsService(CountryActivityDailyRepository a,CityActivityDailyRepository b,CountryRevenueDailyRepository c,CultureCountryDailyRepository d,ArtisanCountryDailyRepository e){countries=a;cities=b;revenues=c;cultures=d;artisans=e;}
 @Transactional public void record(StoredAnalyticsEvent event,JsonNode payload){String country=code(event.contentCountryCode!=null?event.contentCountryCode:event.countryCode);if(country==null)return;LocalDate date=event.occurredAt.atZone(ZoneOffset.UTC).toLocalDate();String type=event.eventType;boolean view=type.toLowerCase(Locale.ROOT).contains("view");boolean interaction=type.startsWith("interaction.")||type.toLowerCase(Locale.ROOT).matches(".*(like|comment|share|favorite).*?");CountryActivityDaily ca=countries.findByStatDateAndCountryCodeAndEventType(date,country,type).orElseGet(()->country(date,country,type));ca.events++;if(view)ca.views++;if(interaction)ca.interactions++;ca.updatedAt=Instant.now();countries.save(ca);if(event.cityId!=null){CityActivityDaily city=cities.findByStatDateAndCountryCodeAndCityIdAndEventType(date,country,event.cityId,type).orElseGet(()->city(date,country,event.cityId,type));city.events++;if(view)city.views++;if(interaction)city.interactions++;city.updatedAt=Instant.now();cities.save(city);}String lower=type.toLowerCase(Locale.ROOT);if(lower.contains("culture")){CultureCountryDaily c=cultures.findByStatDateAndCountryCodeAndContentType(date,country,contentType(payload,type)).orElseGet(()->culture(date,country,contentType(payload,type)));c.events++;if(view)c.views++;if(interaction)c.interactions++;c.updatedAt=Instant.now();cultures.save(c);}if(lower.contains("artisan")||lower.contains("artwork")){ArtisanCountryDaily a=artisans.findByStatDateAndCountryCode(date,country).orElseGet(()->artisan(date,country));a.events++;if(view)a.views++;if(interaction)a.interactions++;a.updatedAt=Instant.now();artisans.save(a);}if(isMoney(type)&&event.currencyCode!=null){CountryRevenueDaily r=revenues.findByStatDateAndCountryCodeAndCurrencyCode(date,country,event.currencyCode).orElseGet(()->revenue(date,country,event.currencyCode));BigDecimal amount=amount(payload);if(type.toLowerCase(Locale.ROOT).contains("refund"))r.refunds=r.refunds.add(amount);else {r.payments++;r.revenue=r.revenue.add(amount);}r.updatedAt=Instant.now();revenues.save(r);}}
 public List<Activity> countries(LocalDate from,LocalDate to){return countries.findByStatDateBetweenOrderByStatDateAsc(from,to).stream().map(x->new Activity(x.statDate,x.countryCode,x.eventType,x.events,x.views,x.interactions)).toList();}public List<Activity> country(String code,LocalDate from,LocalDate to){return countries.findByCountryCodeAndStatDateBetweenOrderByStatDateAsc(norm(code),from,to).stream().map(x->new Activity(x.statDate,x.countryCode,x.eventType,x.events,x.views,x.interactions)).toList();}public List<CityActivity> cities(String code,LocalDate from,LocalDate to){return cities.findByCountryCodeAndStatDateBetweenOrderByStatDateAsc(norm(code),from,to).stream().map(x->new CityActivity(x.statDate,x.countryCode,x.cityId,x.eventType,x.events,x.views,x.interactions)).toList();}public List<CultureActivity> culture(String code,LocalDate from,LocalDate to){return cultures.findByCountryCodeAndStatDateBetweenOrderByStatDateAsc(norm(code),from,to).stream().map(x->new CultureActivity(x.statDate,x.countryCode,x.contentType,x.events,x.views,x.interactions)).toList();}public List<ArtisanActivity> artisans(String code,LocalDate from,LocalDate to){return artisans.findByCountryCodeAndStatDateBetweenOrderByStatDateAsc(norm(code),from,to).stream().map(x->new ArtisanActivity(x.statDate,x.countryCode,x.events,x.views,x.interactions)).toList();}public List<Revenue> revenue(String code,LocalDate from,LocalDate to){return revenues.findByCountryCodeAndStatDateBetweenOrderByStatDateAsc(norm(code),from,to).stream().map(x->new Revenue(x.statDate,x.countryCode,x.currencyCode,x.payments,x.revenue,x.refunds)).toList();}
 private CountryActivityDaily country(LocalDate d,String c,String t){var x=new CountryActivityDaily();x.id=UUID.randomUUID();x.statDate=d;x.countryCode=c;x.eventType=t;return x;}private CityActivityDaily city(LocalDate d,String c,String city,String t){var x=new CityActivityDaily();x.id=UUID.randomUUID();x.statDate=d;x.countryCode=c;x.cityId=city;x.eventType=t;return x;}private CountryRevenueDaily revenue(LocalDate d,String c,String currency){var x=new CountryRevenueDaily();x.id=UUID.randomUUID();x.statDate=d;x.countryCode=c;x.currencyCode=currency;return x;}private CultureCountryDaily culture(LocalDate d,String c,String t){var x=new CultureCountryDaily();x.id=UUID.randomUUID();x.statDate=d;x.countryCode=c;x.contentType=t;return x;}private ArtisanCountryDaily artisan(LocalDate d,String c){var x=new ArtisanCountryDaily();x.id=UUID.randomUUID();x.statDate=d;x.countryCode=c;return x;}private boolean isMoney(String t){String v=t.toLowerCase(Locale.ROOT);return v.contains("payment")||v.contains("ticket.")||v.contains("refund");}private BigDecimal amount(JsonNode p){try{return p.has("amount")?p.path("amount").decimalValue():p.path("totalAmount").decimalValue();}catch(Exception e){return BigDecimal.ZERO;}}private String contentType(JsonNode p,String type){return p.path("contentType").asText(type);}private String code(String v){return v==null||!v.matches("[A-Za-z]{2}")?null:v.toUpperCase(Locale.ROOT);}private String norm(String v){String n=code(v);if(n==null)throw new IllegalArgumentException("countryCode must be ISO-2");return n;}
 public record Activity(LocalDate date,String countryCode,String eventType,long events,long views,long interactions){}public record CityActivity(LocalDate date,String countryCode,String cityId,String eventType,long events,long views,long interactions){}public record CultureActivity(LocalDate date,String countryCode,String contentType,long events,long views,long interactions){}public record ArtisanActivity(LocalDate date,String countryCode,long events,long views,long interactions){}public record Revenue(LocalDate date,String countryCode,String currencyCode,long payments,BigDecimal revenue,BigDecimal refunds){}
}
